using System;
using System.IO;
using System.Runtime.Versioning;
using System.Security.AccessControl;
using System.Security.Principal;

namespace Campground.Shared.Storage
{
    /// <summary>
    /// Folders and files only Jellyfin's own account can read: mode 0700 / 0600 on Linux, and on Windows an ACL of
    /// SYSTEM, Administrators and Jellyfin's account with inheritance off, because <c>C:\ProgramData</c> otherwise
    /// gives every local user read (issue #15). <c>SecretBox</c>'s key files use it, and so can a plugin's own
    /// secrets, such as a certificate's private key (0.20.0, issue #52). On Windows, files created inside a private
    /// folder by anything else inherit its ACL. On Linux they get the creator's umask, and the 0700 folder keeps
    /// other accounts out.
    /// </summary>
    internal static class PrivateFiles
    {
        private const UnixFileMode PrivateFile = UnixFileMode.UserRead | UnixFileMode.UserWrite;
        private const UnixFileMode PrivateFolder = UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute;

        /// <summary>
        /// Creates the folder private, or makes an existing one private. Best effort: a folder another account made
        /// may not let us change it, and then it is only created, no better protected than before.
        /// </summary>
        internal static void CreateFolder(string folder)
        {
            try
            {
                if (OperatingSystem.IsWindows())
                {
                    var info = new DirectoryInfo(folder);
                    if (!info.Exists)
                    {
                        Directory.CreateDirectory(info.Parent!.FullName);
                        info.Create(PrivateFolderSecurity());
                    }
                    else
                    {
                        info.SetAccessControl(PrivateFolderSecurity());
                    }
                }
                else if (!Directory.Exists(folder))
                {
                    Directory.CreateDirectory(Path.GetDirectoryName(folder)!);
                    Directory.CreateDirectory(folder, PrivateFolder);
                }
                else
                {
                    File.SetUnixFileMode(folder, PrivateFolder);
                }
            }
            catch (Exception e) when (e is UnauthorizedAccessException or IOException or PlatformNotSupportedException)
            {
                Directory.CreateDirectory(folder);
            }
        }

        /// <summary>
        /// Creates a file exclusively, private from the first byte, and writes it through to disk. Throws
        /// <see cref="IOException"/> if it already exists, so two writers can't both win. To replace a file, write the
        /// new one under another name in the same folder and move it over the old one; the move keeps it private.
        /// </summary>
        internal static void WriteNew(string path, ReadOnlySpan<byte> data)
        {
            FileStream fs;
            if (OperatingSystem.IsWindows())
            {
                fs = new FileInfo(path).Create(FileMode.CreateNew, FileSystemRights.Write, FileShare.None, 4096, FileOptions.WriteThrough, PrivateFileSecurity());
            }
            else
            {
                // FileShare.Read, not None. On Unix .NET takes the share as a flock after the file exists, so
                // with None a loser reading the empty file (a shared lock) made the winner's exclusive lock fail,
                // and nobody ever wrote the key (seen in shared-ci). Readers wait until it is whole instead.
                fs = new FileStream(path, new FileStreamOptions
                {
                    Mode = FileMode.CreateNew,
                    Access = FileAccess.Write,
                    Share = FileShare.Read,
                    Options = FileOptions.WriteThrough,
                    UnixCreateMode = PrivateFile,
                });
            }

            try
            {
                using (fs)
                {
                    fs.Write(data);
                    fs.Flush(flushToDisk: true);
                }
            }
            catch
            {
                // We created it, so it's ours to remove: a half-written file left behind could be taken as whole.
                try
                {
                    File.Delete(path);
                }
                catch (Exception e) when (e is UnauthorizedAccessException or IOException)
                {
                }

                throw;
            }
        }

        /// <summary>Makes an existing file private, e.g. one an older copy wrote. Best effort, as <see cref="CreateFolder"/>.</summary>
        internal static void Tighten(string path)
        {
            try
            {
                if (OperatingSystem.IsWindows())
                {
                    new FileInfo(path).SetAccessControl(PrivateFileSecurity());
                }
                else
                {
                    File.SetUnixFileMode(path, PrivateFile);
                }
            }
            catch (Exception e) when (e is UnauthorizedAccessException or IOException or PlatformNotSupportedException)
            {
            }
        }

        [SupportedOSPlatform("windows")]
        private static FileSecurity PrivateFileSecurity()
        {
            var security = new FileSecurity();
            security.SetAccessRuleProtection(isProtected: true, preserveInheritance: false);
            foreach (var sid in Owners())
            {
                security.AddAccessRule(new FileSystemAccessRule(sid, FileSystemRights.FullControl, AccessControlType.Allow));
            }

            return security;
        }

        [SupportedOSPlatform("windows")]
        private static DirectorySecurity PrivateFolderSecurity()
        {
            var security = new DirectorySecurity();
            security.SetAccessRuleProtection(isProtected: true, preserveInheritance: false);
            foreach (var sid in Owners())
            {
                security.AddAccessRule(new FileSystemAccessRule(
                    sid,
                    FileSystemRights.FullControl,
                    InheritanceFlags.ContainerInherit | InheritanceFlags.ObjectInherit,
                    PropagationFlags.None,
                    AccessControlType.Allow));
            }

            return security;
        }

        // SYSTEM and Administrators can read anything anyway; leaving them out would only break backups and
        // an admin's repairs. Jellyfin's own account is whoever this process runs as.
        [SupportedOSPlatform("windows")]
        private static SecurityIdentifier[] Owners()
        {
            using var me = WindowsIdentity.GetCurrent();
            return new[]
            {
                new SecurityIdentifier(WellKnownSidType.LocalSystemSid, null),
                new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid, null),
                me.User!,
            };
        }
    }
}
